import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
// C = triu(A * B) for row-major N x N float32 matrices.
// Each block computes a 64x64 tile of C; each thread computes a 4x4 sub-tile.
// Deeper thread-level register blocking (4x4 instead of 2x2) halves the
// shared-memory traffic per FMA vs the previous version.
// Blocks whose tile lies entirely below the diagonal just write zeros.
.version 7.8
.target sm_89
.address_size 64
.visible .entry triu_matmul_kernel(
    .param .u64 triu_matmul_kernel_param_0,
    .param .u64 triu_matmul_kernel_param_1,
    .param .u64 triu_matmul_kernel_param_2,
    .param .u32 triu_matmul_kernel_param_3
)
{
    .reg .pred %p<8>;
    .reg .b32  %r<32>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<32>;
    .shared .align 16 .b8 tile_a[8448];   // 64 x 33 floats (padded)
    .shared .align 16 .b8 tile_b[8320];   // 32 x 65 floats (padded)
    ld.param.u64 %rd1, [triu_matmul_kernel_param_0];  // A
    ld.param.u64 %rd2, [triu_matmul_kernel_param_1];  // B
    ld.param.u64 %rd3, [triu_matmul_kernel_param_2];  // C
    ld.param.u32 %r7,  [triu_matmul_kernel_param_3];  // n
    mov.u32 %r1, %tid.x;     // tx in [0,16)
    mov.u32 %r2, %tid.y;     // ty in [0,16)
    mov.u32 %r3, %ctaid.x;   // bx
    mov.u32 %r4, %ctaid.y;   // by
    shl.b32 %r5, %r3, 6;     // col0 = bx * 64
    shl.b32 %r6, %r4, 6;     // row0 = by * 64
    shl.b32 %r9, %r2, 2;     // ty*4
    shl.b32 %r10, %r1, 2;    // tx*4
    add.s32 %r11, %r6, %r9;  // row_g0 = row0 + ty*4
    add.s32 %r12, %r5, %r10; // col_g0 = col0 + tx*4
    // tile entirely below the diagonal? (col0+63 < row0)
    add.s32 %r8, %r5, 63;
    setp.lt.s32 %p1, %r8, %r6;
    @%p1 bra WRITE_ZERO;
    // 4x4 accumulators
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;
    mov.f32 %f5, 0f00000000;
    mov.f32 %f6, 0f00000000;
    mov.f32 %f7, 0f00000000;
    mov.f32 %f8, 0f00000000;
    mov.f32 %f9, 0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    // shared base addresses
    mov.u64 %rd10, tile_a;
    mov.u64 %rd11, tile_b;
    // per-thread persistent shared bases
    mul.lo.s32 %r20, %r9, 132;          // (ty*4)*33*4 bytes
    cvt.u64.u32 %rd12, %r20;
    add.s64 %rd14, %rd10, %rd12;        // &As[ty*4][0]
    shl.b32 %r21, %r10, 2;              // (tx*4)*4 bytes
    cvt.u64.u32 %rd13, %r21;
    add.s64 %rd15, %rd11, %rd13;        // &Bs[0][tx*4]
    // linear thread id for cooperative loads
    shl.b32 %r14, %r2, 4;
    add.s32 %r14, %r14, %r1;            // tid in [0,256)
    mov.u32 %r13, 0;                    // k0 = 0
K_TILE_LOOP:
    // -------- cooperative tile load (64x32 A tile, 32x64 B tile) --------
    // Fast path: when n is a multiple of 64 every CTA tile is full and all
    // float4 global loads are naturally aligned.
    and.b32 %r22, %r7, 63;
    setp.eq.s32 %p1, %r22, 0;
    @!%p1 bra COOP_LOAD_SCALAR;
    mov.u32 %r15, %r14;                 // idx = tid
VEC_LOAD_LOOP:
    // A tile: 64 rows x 8 float4 = 512 vectors, 2 per thread
    shr.u32 %r16, %r15, 3;              // rr = idx / 8
    and.b32 %r17, %r15, 7;
    shl.b32 %r17, %r17, 2;              // cc = (idx % 8) * 4
    mul.lo.s32 %r20, %r16, 33;
    add.s32 %r20, %r20, %r17;           // rr*33 + cc
    shl.b32 %r21, %r20, 2;
    cvt.u64.u32 %rd12, %r21;
    add.s32 %r18, %r6, %r16;            // row0+rr
    add.s32 %r19, %r13, %r17;           // k0+cc
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd1, %rd7;
    ld.global.v4.f32 {%f25, %f26, %f27, %f28}, [%rd8];
    add.s64 %rd9, %rd10, %rd12;
    st.shared.f32 [%rd9], %f25;
    st.shared.f32 [%rd9+4], %f26;
    st.shared.f32 [%rd9+8], %f27;
    st.shared.f32 [%rd9+12], %f28;
    // B tile: 32 rows x 16 float4 = 512 vectors, 2 per thread
    shr.u32 %r16, %r15, 4;              // rr = idx / 16
    and.b32 %r17, %r15, 15;
    shl.b32 %r17, %r17, 2;              // cc = (idx % 16) * 4
    mul.lo.s32 %r20, %r16, 65;
    add.s32 %r20, %r20, %r17;           // rr*65 + cc
    shl.b32 %r21, %r20, 2;
    cvt.u64.u32 %rd12, %r21;
    add.s32 %r18, %r13, %r16;           // k0+rr
    add.s32 %r19, %r5, %r17;            // col0+cc
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.v4.f32 {%f25, %f26, %f27, %f28}, [%rd8];
    add.s64 %rd9, %rd11, %rd12;
    st.shared.f32 [%rd9], %f25;
    st.shared.f32 [%rd9+4], %f26;
    st.shared.f32 [%rd9+8], %f27;
    st.shared.f32 [%rd9+12], %f28;
    add.s32 %r15, %r15, 256;
    setp.lt.s32 %p5, %r15, 512;
    @%p5 bra VEC_LOAD_LOOP;
    bra COOP_LOAD_DONE;
COOP_LOAD_SCALAR:
    mov.u32 %r15, %r14;                 // idx = tid
COOP_LOAD_LOOP:
    // A[row0+rr][k0+cc], 64x32 scalars, zero-fill out of bounds
    shr.u32 %r16, %r15, 5;              // rr = idx / 32
    and.b32 %r17, %r15, 31;             // cc = idx % 32
    mul.lo.s32 %r20, %r16, 33;
    add.s32 %r20, %r20, %r17;
    shl.b32 %r21, %r20, 2;
    cvt.u64.u32 %rd12, %r21;
    add.s32 %r18, %r6, %r16;
    add.s32 %r19, %r13, %r17;
    setp.lt.s32 %p2, %r18, %r7;
    setp.lt.s32 %p3, %r19, %r7;
    and.pred %p4, %p2, %p3;
    mov.f32 %f25, 0f00000000;
    @!%p4 bra A_LOAD_DONE;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd1, %rd7;
    ld.global.f32 %f25, [%rd8];
A_LOAD_DONE:
    add.s64 %rd9, %rd10, %rd12;
    st.shared.f32 [%rd9], %f25;
    // B[k0+rr][col0+cc], 32x64 scalars, zero-fill out of bounds
    shr.u32 %r16, %r15, 6;              // rr = idx / 64
    and.b32 %r17, %r15, 63;             // cc = idx % 64
    mul.lo.s32 %r20, %r16, 65;
    add.s32 %r20, %r20, %r17;
    shl.b32 %r21, %r20, 2;
    cvt.u64.u32 %rd12, %r21;
    add.s32 %r18, %r13, %r16;
    add.s32 %r19, %r5, %r17;
    setp.lt.s32 %p2, %r18, %r7;
    setp.lt.s32 %p3, %r19, %r7;
    and.pred %p4, %p2, %p3;
    mov.f32 %f25, 0f00000000;
    @!%p4 bra B_LOAD_DONE;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f25, [%rd8];
B_LOAD_DONE:
    add.s64 %rd9, %rd11, %rd12;
    st.shared.f32 [%rd9], %f25;
    add.s32 %r15, %r15, 256;
    setp.lt.s32 %p5, %r15, 2048;
    @%p5 bra COOP_LOAD_LOOP;
COOP_LOAD_DONE:
    bar.sync 0;
    // -------- 4x4 register-blocked FMA over 32-wide k tile --------
    mov.u32 %r26, 0;                    // kk = 0
INNER_K_LOOP:
    shl.b32 %r27, %r26, 2;              // kk*4
    cvt.u64.u32 %rd16, %r27;
    add.s64 %rd17, %rd14, %rd16;
    ld.shared.f32 %f17, [%rd17];        // a0 = As[ty*4][kk]
    ld.shared.f32 %f18, [%rd17+132];    // a1 = As[ty*4+1][kk]
    ld.shared.f32 %f19, [%rd17+264];    // a2 = As[ty*4+2][kk]
    ld.shared.f32 %f20, [%rd17+396];    // a3 = As[ty*4+3][kk]
    mul.lo.s32 %r29, %r26, 260;         // kk*65*4
    cvt.u64.u32 %rd18, %r29;
    add.s64 %rd19, %rd15, %rd18;
    ld.shared.f32 %f21, [%rd19];        // b0 = Bs[kk][tx*4]
    ld.shared.f32 %f22, [%rd19+4];      // b1 = Bs[kk][tx*4+1]
    ld.shared.f32 %f23, [%rd19+8];      // b2 = Bs[kk][tx*4+2]
    ld.shared.f32 %f24, [%rd19+12];     // b3 = Bs[kk][tx*4+3]
    fma.rn.f32 %f1,  %f17, %f21, %f1;
    fma.rn.f32 %f2,  %f17, %f22, %f2;
    fma.rn.f32 %f3,  %f17, %f23, %f3;
    fma.rn.f32 %f4,  %f17, %f24, %f4;
    fma.rn.f32 %f5,  %f18, %f21, %f5;
    fma.rn.f32 %f6,  %f18, %f22, %f6;
    fma.rn.f32 %f7,  %f18, %f23, %f7;
    fma.rn.f32 %f8,  %f18, %f24, %f8;
    fma.rn.f32 %f9,  %f19, %f21, %f9;
    fma.rn.f32 %f10, %f19, %f22, %f10;
    fma.rn.f32 %f11, %f19, %f23, %f11;
    fma.rn.f32 %f12, %f19, %f24, %f12;
    fma.rn.f32 %f13, %f20, %f21, %f13;
    fma.rn.f32 %f14, %f20, %f22, %f14;
    fma.rn.f32 %f15, %f20, %f23, %f15;
    fma.rn.f32 %f16, %f20, %f24, %f16;
    add.s32 %r26, %r26, 1;
    setp.lt.s32 %p6, %r26, 32;
    @%p6 bra INNER_K_LOOP;
    bar.sync 0;
    add.s32 %r13, %r13, 32;
    setp.lt.s32 %p7, %r13, %r7;
    @%p7 bra K_TILE_LOOP;
    // -------- store 4x4 results with upper-triangular mask --------
    mov.f32 %f0, 0f00000000;
    // ---- sub-tile row 0 (row = %r11) ----
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra ST_0;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra ST_0;
    setp.ge.s32 %p4, %r12, %r11;
    selp.f32 %f25, %f1, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_0:
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra ST_1;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_1;
    setp.ge.s32 %p4, %r19, %r11;
    selp.f32 %f25, %f2, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_1:
    add.s32 %r19, %r12, 2;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra ST_2;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_2;
    setp.ge.s32 %p4, %r19, %r11;
    selp.f32 %f25, %f3, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_2:
    add.s32 %r19, %r12, 3;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra ST_3;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_3;
    setp.ge.s32 %p4, %r19, %r11;
    selp.f32 %f25, %f4, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_3:
    // ---- sub-tile row 1 (row = %r11+1) ----
    add.s32 %r18, %r11, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_4;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra ST_4;
    setp.ge.s32 %p4, %r12, %r18;
    selp.f32 %f25, %f5, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_4:
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_5;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_5;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f6, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_5:
    add.s32 %r19, %r12, 2;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_6;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_6;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f7, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_6:
    add.s32 %r19, %r12, 3;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_7;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_7;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f8, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_7:
    // ---- sub-tile row 2 (row = %r11+2) ----
    add.s32 %r18, %r11, 2;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_8;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra ST_8;
    setp.ge.s32 %p4, %r12, %r18;
    selp.f32 %f25, %f9, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_8:
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_9;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_9;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f10, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_9:
    add.s32 %r19, %r12, 2;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_10;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_10;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f11, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_10:
    add.s32 %r19, %r12, 3;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_11;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_11;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f12, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_11:
    // ---- sub-tile row 3 (row = %r11+3) ----
    add.s32 %r18, %r11, 3;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_12;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra ST_12;
    setp.ge.s32 %p4, %r12, %r18;
    selp.f32 %f25, %f13, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_12:
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_13;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_13;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f25, %f14, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f25;
ST_13:
    add.s32 %r19, %r12, 2;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra ST_14;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra ST_14;
